head.script:
scwin.onpageload = function () {
    let userId = $p.getComponentById("mf_pg_header").getWindow().scwin.USER_ID;
    let pjtId = $p.parent().scwin.SEL_PJT_ID;

    console.log('로그인한 userID : ' , userId);
    console.log('현재 pjtID : ' , pjtId);
    dmp_searchVo.set("userId", userId);
    dmp_searchVo.set("pjtId", pjtId);

    scwin.loadTaskList();
    document.addEventListener('dragstart', scwin.handleDragStart);
    document.addEventListener('dragover', scwin.handleDragOver);
    document.addEventListener('drop', scwin.handleDrop);
    document.addEventListener('dragend', scwin.handleDragEnd);
};

scwin.loadTaskList = function() {

    $c.sbm.execute($p, sbm_selectTaskList);
};

scwin.sbm_selectTaskList_submitdone = function(e) {
    var elData = e.responseJSON.elData;
    console.log(elData);
    if (elData && elData.designVoList) {
        dlt_designVoList.setJSON(elData.designVoList);
        scwin.renderKanbanBoard();
        scwin.updateStatistics();
    } else {
        scwin.renderEmptyBoard();
    }
};

scwin.renderKanbanBoard = function() {
    var taskData = dlt_designVoList.getAllJSON();
    console.log("renderKanbanBoard >> taskData : ", taskData);
    var waitingTasks = taskData.filter(task => task.taskStatus === "대기");
    var progressTasks = taskData.filter(task => task.taskStatus === "진행중");
    var completedTasks = taskData.filter(task => task.taskStatus === "완료");

    scwin.renderColumn(scwin.getRealId("waiting_tasks"), waitingTasks);
    scwin.renderColumn(scwin.getRealId("progress_tasks"), progressTasks);
    scwin.renderColumn(scwin.getRealId("completed_tasks"), completedTasks);

    scwin.updateColumnCounts(waitingTasks.length, progressTasks.length, completedTasks.length);
};

scwin.getRealId = function(suffix){
    const el = document.querySelector(`[id$="${suffix}"]`);
    return el ? el.id : null;
};

scwin.updateColumnCounts = function(waiting, progress, completed) {
    var waitingCount = document.getElementById(scwin.getRealId("waiting_count"));
    var progressCount = document.getElementById(scwin.getRealId('progress_count'));
    var completedCount = document.getElementById(scwin.getRealId('completed_count'));

    console.log("카운트 업데이트:", {
        waitingCount: waitingCount,
        progressCount: progressCount, 
        completedCount: completedCount
    });

    if (waitingCount) waitingCount.textContent = waiting + "개";
    if (progressCount) progressCount.textContent = progress + "개";
    if (completedCount) completedCount.textContent = completed + "개";
};


scwin.renderColumn = function(columnId, tasks) {
    console.log("컬럼 렌더링 시도:", columnId, "업무 개수:", tasks.length);

    var columnBody = document.getElementById(columnId);
    if (!columnBody) {
        console.error("컬럼을 찾을 수 없습니다:", columnId);
        console.log("사용 가능한 요소들:", document.querySelectorAll('[id*="tasks"]'));
        return;
    }

    console.log("컬럼 찾음:", columnId, columnBody);
    columnBody.innerHTML = '';

    if (tasks.length === 0) {
        columnBody.innerHTML = '<div class="empty_placeholder">업무를 드래그하세요</div>';
        return;
    }

    tasks.forEach(function(task) {
        var taskCard = scwin.createTaskCard(task);
        columnBody.appendChild(taskCard);
    });

    console.log("컬럼 렌더링 완료:", columnId);
};

scwin.createTaskCard = function(task) {
    var card = document.createElement('div');
    card.className = 'task_card';
    card.draggable = true;
    card.dataset.taskId = task.taskId;
    card.dataset.currentStatus = task.taskStatus;

    var stageName = Number(task.isDesign) ? "설계" : "개발"
    var stageClass = Number(task.isDesign) ? "design" : "development"; 

    card.innerHTML = 
        '<div class="task_name">' + (task.taskName || '제목 없음') + '</div>' +
        '<div class="task_info">' +
            '<span class="task_assignee">' + (task.taskAsi || '미지정') + '</span>' +
            '<span class="task_stage ' + stageClass +'">' + stageName + '</span>' +
        '</div>' +
        '<div class="task_dates">' +
            '시작 예정: ' + (task.taskSt || '미정') + ' | 완료 예정: ' + (task.taskEt || '미정') +
        '</div>' +
        '<div style="margin-top:8px;">' +
            '<button class="action_btn task_detail_btn" data-task-id="' + task.taskId + '">상세</button>' +
        '</div>';

    // 이벤트 리스너로 상세 버튼 클릭 이벤트 등록
    setTimeout(function() {
        var detailBtn = card.querySelector('.task_detail_btn');
        if (detailBtn) {
            detailBtn.addEventListener('click', function(e) {
                e.stopPropagation(); // 드래그 이벤트와 충돌 방지
                var taskId = this.getAttribute('data-task-id');
                scwin.openTaskDetailPopup(taskId);
            });
        }
    }, 10);

    return card;
};


// 업무 상세 팝업 열기 함수를 여기로 이동 (createTaskCard보다 먼저 정의)
scwin.openTaskDetailPopup = function(taskId) {
    console.log("업무 상세 팝업 열기:", taskId);

    var taskData = dlt_designVoList.getAllJSON();
    var task = null;

    for (var i = 0; i < taskData.length; i++) {
        if (taskData[i].taskId === taskId) {
            task = taskData[i];
            break;
        }
    }

    if (!task) {
        alert("업무 정보를 찾을 수 없습니다.");
        return;
    }

    // DesignPopup.xml에 전달할 데이터
    var jsnPopupData = {
        "type": "json",
        "name": "taskData",
        "data": task
    };

    var options = {
        id: "task_detail_popup",
        type: "wframePopup",
        width: "750px",
        height: "700px",
        top: "30px",
        left: "200px",
        popupName: "업무 상세 정보",
        modal: true,
        closeAction: "scwin.detailPopup_closeAction",
        dataObject: jsnPopupData
    };

    console.log("설계 업무 여부", task.isDesign);
    if(task.isDesign === "1") $p.openPopup("/InsWebApp/ui/task/design/DesignPopup.xml", options);
    else if(task.isDesign === "0") $p.openPopup("/InsWebApp/ui/task/develop/DevelopPopup.xml", options);

};

scwin.updateStatistics = function() {
    var taskData = dlt_designVoList.getAllJSON();
    var total = taskData.length;
    var waiting = taskData.filter(task => task.taskStatus === "대기").length;
    var progress = taskData.filter(task => task.taskStatus === "진행중").length;
    var completed = taskData.filter(task => task.taskStatus === "완료").length;

    dmp_stats.set("totalTasks", total);
    dmp_stats.set("waitingTasks", waiting);
    dmp_stats.set("progressTasks", progress);
    dmp_stats.set("completedTasks", completed);
};

scwin.renderEmptyBoard = function() {
    ['waiting_tasks', 'progress_tasks', 'completed_tasks'].forEach(function(columnId) {
        var realId = scwin.getRealId(columnId);
        var columnBody = document.getElementById(realId);
        if (columnBody) {
            columnBody.innerHTML = '<div class="empty_placeholder">업무가 없습니다</div>';
        }
    });
};

// 드래그 앤 드롭
scwin.draggedElement = null;
scwin.draggedTaskId = null;
scwin.originalStatus = null;

scwin.handleDragStart = function(e) {
    if (!e.target.classList.contains('task_card')) return;

    scwin.draggedElement = e.target;
    scwin.draggedTaskId = e.target.dataset.taskId;
    scwin.originalStatus = e.target.dataset.currentStatus;

    e.target.classList.add('dragging');
    e.dataTransfer.effectAllowed = 'move';

    console.log("드래그 시작:", {
        taskId: scwin.draggedTaskId,
        originalStatus: scwin.originalStatus,
        element: e.target
    });
};

scwin.handleDragOver = function(e) {
    e.preventDefault();
    var dropTarget = scwin.findDropTarget(e.target);
    if (dropTarget) {
        dropTarget.classList.add('drag_over');
    }
};

scwin.handleDrop = function(e) {
    e.preventDefault();

    console.log("드롭 이벤트 발생:", {
        draggedTaskId: scwin.draggedTaskId,
        originalStatus: scwin.originalStatus
    });

    if (!scwin.draggedTaskId) {
        console.log("드래그된 업무 ID가 없습니다.");
        return;
    }

    var dropTarget = scwin.findDropTarget(e.target);
    if (!dropTarget) {
        console.log("유효한 드롭 타겟을 찾지 못했습니다.");
        return;
    }

    console.log("드롭 타겟 찾음:", dropTarget.id);

    var newStatus = scwin.getStatusFromColumn(dropTarget.id);
    console.log("새로운 상태:", newStatus);

    if (!newStatus || newStatus === scwin.originalStatus) {
        console.log("같은 상태로 이동하거나 잘못된 컬럼입니다.");
        scwin.cleanupDrag();
        return;
    }

    console.log("상태 업데이트 실행:", scwin.draggedTaskId, scwin.originalStatus, "→", newStatus);
    scwin.updateTaskStatus(scwin.draggedTaskId, newStatus);

    scwin.cleanupDrag();
};

scwin.handleDragEnd = function(e) {
    scwin.cleanupDrag();
};

scwin.cleanupDrag = function() {
    if (scwin.draggedElement) {
        scwin.draggedElement.classList.remove('dragging');
    }
    document.querySelectorAll('.drag_over').forEach(function(element) {
        element.classList.remove('drag_over');
    });
    scwin.draggedElement = null;
    scwin.draggedTaskId = null;
    scwin.originalStatus = null;
};

scwin.findDropTarget = function(element) {
    var current = element;
    while (current && current !== document.body) {
        if (current.id && (current.id === scwin.getRealId('waiting_tasks') || current.id === scwin.getRealId('progress_tasks') || current.id === scwin.getRealId('completed_tasks'))) {
            return current;
        }
        current = current.parentElement;
        console.log(current);
    }
    return null;
};

scwin.getStatusFromColumn = function(columnId) {
    switch(columnId) {
        case scwin.getRealId('waiting_tasks'): return '대기';
        case scwin.getRealId('progress_tasks') : return '진행중';
        case scwin.getRealId('completed_tasks'): return '완료';
        default: return null;
    }
};

scwin.updateTaskStatus = function(taskId, newStatus) {
    console.log("업무 상태 업데이트 시작:", taskId, "→", newStatus);

    var taskData = dlt_designVoList.getAllJSON();
    var updatedTask = null;
    var updatedIndex = -1;

    for (var i = 0; i < taskData.length; i++) {
        if (taskData[i].taskId === taskId) {
            console.log("업무 찾음:", taskData[i]);
            taskData[i].taskStatus = newStatus;
            taskData[i].rowStatus = "U";
            updatedTask = taskData[i];
            updatedIndex = i;
            break;
        }
    }

    if (!updatedTask) {
        console.error("업무를 찾을 수 없습니다:", taskId);
        return;
    }

    console.log("업데이트될 업무:", updatedTask);

    // 즉시 DataCollection 업데이트 및 화면 반영
    dlt_designVoList.setCellData(updatedIndex, "taskStatus", newStatus);
    dlt_designVoList.setCellData(updatedIndex, "rowStatus", "U");

    // 즉시 화면 업데이트
    scwin.renderKanbanBoard();
    scwin.updateStatistics();

    // DesignList.xml과 동일한 방식으로 서버 요청
    var reqObj = {
        "elData": {
            "wbsVoList": [updatedTask]
        }
    };

    console.log("서버 요청 데이터:", reqObj);
    $c.sbm.execute($p, sbm_saveDesignVoList, reqObj);
};


scwin.sbm_saveDesignVoList_submitdone = function (e) {
    console.log("업무 상태 업데이트 완료:", e);

    var elHeader = e.responseJSON.elHeader;
    if (elHeader == null || elHeader == "" || elHeader == "undefiend" || elHeader.resSuc == false) {
        alert(`업데이트 실패\n에러코드 : ${elHeader.resCode}\n에러메시지 : ${elHeader.resMsg}`);
        // 실패 시 데이터 다시 로드 (원래 상태로 복원)
        scwin.loadTaskList();
        return false;
    } else {
        console.log("업무 상태 업데이트 성공");

        // DataCollection에 변경된 데이터를 다시 설정 !!!
        dlt_designVoList.setJSON(dlt_designVoList.getAllJSON());

        // 성공 시 칸반 보드 즉시 다시 렌더링
        setTimeout(function() {
            scwin.renderKanbanBoard();
            scwin.updateStatistics();
        }, 100);
    }
};

// 팝업 닫기 액션
scwin.detailPopup_closeAction = function(argRuntimeID, argJsnInfo) {
    console.log("팝업 닫기:", argJsnInfo);
    scwin.refreshBoard();
    return true;
};

scwin.refreshBoard = function() {
    scwin.loadTaskList();
};

// DesignPopup.xml 호환성을 위한 함수들 추가
scwin.btn_search_onclick = function() {
    console.log("팝업에서 부모 새로고침 요청");
    scwin.refreshBoard();
};

// DesignList.xml 호환성을 위한 함수 별칭
scwin.sbm_designList_submitdone = function(e) {
    return scwin.sbm_selectTaskList_submitdone(e);
};
